package com.mitraa.hackathon.submission;
import com.mitraa.hackathon.registration.Registration; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="submissions")
public class Submission { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="registration_id",unique=true) private Registration registration; @Column(nullable=false,length=140) private String projectName; @Column(nullable=false,length=2000) private String problemStatement; @Column(nullable=false,length=4000) private String solutionSummary; @Column(nullable=false,length=1000) private String technologyStack; @Column(length=500) private String repositoryUrl; @Column(length=500) private String demoUrl; @Column(nullable=false,length=2000) private String responsibleAi; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private SubmissionStatus status=SubmissionStatus.DRAFT; @Column(nullable=false) private Instant updatedAt=Instant.now(); private Instant submittedAt; public Long getId(){return id;} public Registration getRegistration(){return registration;} public void setRegistration(Registration v){registration=v;} public String getProjectName(){return projectName;} public void setProjectName(String v){projectName=v;} public String getProblemStatement(){return problemStatement;} public void setProblemStatement(String v){problemStatement=v;} public String getSolutionSummary(){return solutionSummary;} public void setSolutionSummary(String v){solutionSummary=v;} public String getTechnologyStack(){return technologyStack;} public void setTechnologyStack(String v){technologyStack=v;} public String getRepositoryUrl(){return repositoryUrl;} public void setRepositoryUrl(String v){repositoryUrl=v;} public String getDemoUrl(){return demoUrl;} public void setDemoUrl(String v){demoUrl=v;} public String getResponsibleAi(){return responsibleAi;} public void setResponsibleAi(String v){responsibleAi=v;} public SubmissionStatus getStatus(){return status;} public void setStatus(SubmissionStatus v){status=v;} public Instant getUpdatedAt(){return updatedAt;} public void touch(){updatedAt=Instant.now();} public void submit(){status=SubmissionStatus.SUBMITTED;submittedAt=Instant.now();updatedAt=submittedAt;} public Instant getSubmittedAt(){return submittedAt;} }
